<script setup lang="ts">import {ArrowRight} from 'lucide-vue-next';import {categories,products} from '../data';import PageHero from '../components/PageHero.vue';const productCount=(category:string)=>products.filter(p=>p.category===category).length;</script><template><PageHero eyebrow="Explore" title="Shop by Category" subtitle="Find the perfect sweet for every mood, moment and celebration."/><section class="section"><div class="container category-grid"><RouterLink v-for="c in categories" :key="c.id" :to="`/shop?category=${c.id}`" class="category-card"><img :src="c.image"><div><span>{{c.nameAr}}</span><h2>{{c.name}}</h2><p>{{c.description}}</p><b>{{productCount(c.id)}} available products <ArrowRight :size="17"/></b></div></RouterLink></div></section></template>
